		pos.y = r.position.y - panel.size.y - 16.0
	pos.x = clampf(pos.x, 16.0, 2400.0 - panel.size.x - 16.0)
	pos.y = clampf(pos.y, 16.0, 1400.0 - panel.size.y - 16.0)
	panel.position = pos
	sel_hover_panel = panel

