	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _nearest(p: Vector3, walls: Array) -> float:
	var best := 999.0
	for w in walls:
		var n3: Node3D = w
		var dx: float = n3.position.x - p.x
		var dz: float = n3.position.z - p.z
		var d: float = sqrt(dx * dx + dz * dz)
		if d < best:
			best = d
	return best

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager") as BattleManager
		if bm != null:
			bm._start_game("亚瑟")
	elif t == 320:
		var walls: Array = get_tree().get_nodes_in_group("walls")
		print("G walls=", walls.size())
		var fbs := [Vector2(-62, 62), Vector2(62, -62)]
		var holes: Array = []
		var worst := 0.0
		var step := 1.0
		var v := -63.0
		while v <= 63.0:
			for p in [Vector3(-63, 0, v), Vector3(63, 0, v), Vector3(v, 0, -63), Vector3(v, 0, 63)]:
				var pv := Vector2(p.x, p.z)
				var near_f := false
				for fb in fbs:
					if pv.distance_to(fb) < 11.0:
						near_f = true
				if near_f:
					continue
				var d := _nearest(p, walls)
				if d > worst:
					worst = d
				if d > 1.6:
					holes.append([p, "%.2f" % d])
			v += step
		print("G worst_gap=", "%.2f" % worst, " holes(>1.6)=", holes.size())
		var shown := 0
		for h in holes:
			if shown < 12:
				print("G hole ", h[0], " d=", h[1])
				shown += 1
		# 塔附近墙（塔外墙应已删除）
		for tr in bm.turrets:
			var n3: Node3D = tr
			if str(tr.tower_type) != "outer" and str(tr.tower_type) != "inner":
				continue
			if absf(absf(n3.position.x) - absf(n3.position.z)) < 8.0:
				continue
			print("G tower ", n3.position, " nearest=", "%.2f" % _nearest(n3.position, walls))
	elif t == 360:
		get_tree().quit()
