func _collect(n: Node, out: Array) -> void:
	if n is MeshInstance3D and n.mesh != null:
		out.append(n)
	for c in n.get_children():
		_collect(c, out)

func _bounds(n: Node) -> Array:
	var box := AABB()
	var first := true
	var tri := 0
	var meshes: Array = []
	_collect(n, meshes)
	for mi in meshes:
		var mb: AABB = mi.mesh.get_aabb()
		var wb: AABB = (mi.transform if mi.get_parent() == n else mi.get_parent().transform * mi.transform) * mb
		box = wb if first else box.merge(wb)
		first = false
		tri += mi.mesh.get_faces().size() / 3
	return [box.size, tri, meshes.size()]

