				if absf(c1.r - c2.r) + absf(c1.g - c2.g) + absf(c1.b - c2.b) > 0.12:
					diff += 1
				if (c1.r + c1.g + c1.b) / 3.0 > 0.12:
					lit1 += 1
				if (c2.r + c2.g + c2.b) / 3.0 > 0.12:
					lit2 += 1
		print("M portraits_diff=", diff, "/", tot, " lit1=", lit1, " lit2=", lit2)
