extends Node
var bm: Node
var f := 0
var done := false

func _ready() -> void:
	add_child(load("res://scenes/battle.tscn").instantiate())
	bm = get_tree().get_first_node_in_group("battle_manager")

func _physics_process(_d: float) -> void:
	f += 1
	if f == 3:
		bm._start_game_body("鲁班七号")
		return
	if f < 200 or done:
		return
	done = true
	# 1) 统计正在 process / physics_process 的节点，按脚本归类
	var tally := {}
	var total := 0
	var stack: Array = [get_tree().root]
	while not stack.is_empty():
		var n: Node = stack.pop_back()
		total += 1
		var p := n.is_processing() or n.is_physics_processing()
		if p:
			var key := n.get_class()
			var sc = n.get_script()
			if sc != null:
				key = sc.resource_path.get_file()
			tally[key] = int(tally.get(key, 0)) + 1
		for c in n.get_children():
			stack.append(c)
	print("PROBE|nodes=", total)
	var keys := tally.keys()
	keys.sort_custom(func(a, b): return int(tally[a]) > int(tally[b]))
	print("PROBE|processing_by_script=", keys)
	for k in keys:
		print("PROBE|  ", k, " x", tally[k])
	# 2) 单独测 UI_Manager.update 的耗时
	var t0 := Time.get_ticks_usec()
	for i in range(20):
		UiManager.update(bm)
	var ui_ms := float(Time.get_ticks_usec() - t0) / 20.0 / 1000.0
	print("PROBE|ui_update_ms=%.3f" % ui_ms)
	# 3) BattleManager._process 单独耗时（调用一次，注意会推进相机/UI）
	t0 = Time.get_ticks_usec()
	bm._process(1.0 / 60.0)
	var bm_ms := float(Time.get_ticks_usec() - t0) / 1000.0
	print("PROBE|bm_process_ms=%.3f" % bm_ms)
	print("PROBE|DONE")
	get_tree().quit()
